import React, { useState } from 'react';

const AdminDashboard = () => {
  // État pour la gestion des cours
  const [courseToEdit, setCourseToEdit] = useState({
    title: "Hacking Éthique & Pentest : Les Fondations",
    status: "published",
    lessons: [{ id: 1, title: "Introduction au Pentesting", duration: "12:00", url: "https://video-1.mp4" }]
  });

  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const addLesson = () => {
    setCourseToEdit({ ...courseToEdit, lessons: [...courseToEdit.lessons, { id: Date.now(), title: "", duration: "00:00", url: "" }] });
  };

  const updateLesson = (id, field, value) => {
    setCourseToEdit({ ...courseToEdit, lessons: courseToEdit.lessons.map(l => l.id === id ? { ...l, [field]: value } : l) });
  };

  const removeLesson = (id) => {
    setCourseToEdit({ ...courseToEdit, lessons: courseToEdit.lessons.filter(l => l.id !== id) });
  };

  const handlePublish = (e) => {
    e.preventDefault();
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    }, 2000);
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 font-sans p-8 antialiased">
      <div className="max-w-5xl mx-auto space-y-10">
        
        {/* EN-TÊTE ADMIN */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 border-b border-slate-900 pb-8">
          <div>
            <span className="text-[10px] font-mono text-blue-500 tracking-[0.2em] uppercase">Console de Gestion</span>
            <h1 className="text-2xl font-bold text-white tracking-tight">PANNEAU D'ADMINISTRATION PROFESSEUR</h1>
          </div>
          <button onClick={handlePublish} className="bg-white text-slate-950 px-6 py-2.5 rounded-lg text-xs font-bold uppercase hover:bg-blue-500 hover:text-white transition-all shadow-lg">
            {isSaving ? "Déploiement..." : "Publier la mise à jour"}
          </button>
        </div>

        {/* ANALYSE FINANCIÈRE */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-slate-950 border border-slate-900 p-6 rounded-xl">
            <p className="text-[10px] uppercase text-slate-500 font-mono">Chiffre d'affaires total</p>
            <p className="text-xl font-bold mt-2">1,240,000 CFA</p>
          </div>
          <div className="bg-slate-950 border border-slate-900 p-6 rounded-xl">
            <p className="text-[10px] uppercase text-slate-500 font-mono">Ventes par cours (Top)</p>
            <p className="text-sm mt-2 font-bold">Hacking Offensif: 45 ventes</p>
          </div>
          <div className="bg-slate-950 border border-slate-900 p-6 rounded-xl">
            <p className="text-[10px] uppercase text-slate-500 font-mono">Répartition paiement</p>
            <p className="text-sm mt-2 font-bold">MTN: 60% | Wave: 30% | Card: 10%</p>
          </div>
        </div>

        {/* SECTION GESTION COURS */}
        <div className="bg-slate-950/40 border border-slate-900 rounded-xl p-6 space-y-6">
          <h3 className="text-xs font-bold text-white uppercase tracking-wider">Configuration module</h3>
          <input 
            type="text" value={courseToEdit.title}
            onChange={(e) => setCourseToEdit({...courseToEdit, title: e.target.value})}
            className="w-full bg-slate-900 border border-slate-800 rounded-lg px-4 py-2.5 text-sm text-white focus:outline-none"
          />
          
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <span className="text-[10px] font-mono uppercase text-slate-500">Programme ({courseToEdit.lessons.length} leçons)</span>
              <button onClick={addLesson} className="text-[10px] text-blue-500 uppercase font-bold">+ Ajouter</button>
            </div>
            {courseToEdit.lessons.map((lesson, index) => (
              <div key={lesson.id} className="grid md:grid-cols-12 gap-4 items-center bg-slate-900 p-4 rounded border border-slate-800">
                <input className="md:col-span-5 bg-slate-950 p-2 text-xs rounded" value={lesson.title} onChange={(e) => updateLesson(lesson.id, 'title', e.target.value)} placeholder="Titre..." />
                <input className="md:col-span-2 bg-slate-950 p-2 text-xs rounded" value={lesson.duration} onChange={(e) => updateLesson(lesson.id, 'duration', e.target.value)} placeholder="00:00" />
                <input className="md:col-span-4 bg-slate-950 p-2 text-xs rounded" value={lesson.url} onChange={(e) => updateLesson(lesson.id, 'url', e.target.value)} placeholder="URL..." />
                <button onClick={() => removeLesson(lesson.id)} className="text-red-500 text-xs font-bold uppercase">✕</button>
              </div>
            ))}
          </div>
        </div>

        {/* SECTION SUPPORT */}
        <div className="bg-slate-950 border border-slate-900 rounded-xl overflow-hidden">
          <div className="p-6 border-b border-slate-900"><h3 className="text-xs font-bold uppercase">Messages Support</h3></div>
          <table className="w-full text-xs text-left">
            <thead className="bg-slate-900 uppercase text-slate-500"><tr><th className="p-4">Utilisateur</th><th className="p-4">Message</th><th className="p-4">Action</th></tr></thead>
            <tbody className="divide-y divide-slate-900">
              <tr><td className="p-4 font-mono">etudiant@email.com</td><td className="p-4">Problème accès module 4</td><td className="p-4"><button className="text-emerald-500 uppercase font-bold">[ Traité ]</button></td></tr>
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
};

export default AdminDashboard;
